package feature.review.data.modeldata class ReviewResponse(    val id: String,    val userId: String,    val userName: String,    val rating: Int,                   // من 1 لـ 5    val comment: String? = null,    val createdAt: String? = null)data class ReviewListResponse(    val reviews: List<ReviewResponse>,    val page: Int,    val pageSize: Int,    val totalCount: Int,    val averageRating: Double? = null)data class CreateReviewRequest(    val rating: Int,    val comment: String? = null)